import { globalScene } from "#app/global-scene";
import type { Pokemon } from "#field/pokemon";
import { InkGradePostFX } from "#app/pipelines/ink-grade";

const TYPE_INK = [
  0xd8d2c0, 0xff5a2a, 0x3aa6ff, 0x4fd463, 0xffd93a, 0x8ff0ff, 0xff4466, 0xc05cff, 0xd9a35a,
  0x9fc3ff, 0xff4fae, 0xa8e03a, 0xb59a6a, 0x7a5cff, 0x5a6cff, 0x5a4a66, 0xb8c8d8, 0xff9fe0,
];

let ready = false;

function makeSplatTexture(key: string, seed: number) {
  const g = globalScene.make.graphics({ x: 0, y: 0 }, false);
  const S = 32;
  let s = seed;
  const rnd = () => ((s = (s * 16807) % 2147483647) / 2147483647);
  g.fillStyle(0xffffff, 1);
  g.fillCircle(S / 2, S / 2, 7 + rnd() * 2);
  for (let i = 0; i < 7; i++) {
    const a = rnd() * Math.PI * 2;
    const d = 6 + rnd() * 8;
    g.fillCircle(S / 2 + Math.cos(a) * d, S / 2 + Math.sin(a) * d, 1.5 + rnd() * 3);
  }
  g.generateTexture(key, S, S);
  g.destroy();
}

export function initAgentFx(): void {
  if (ready) {
    return;
  }
  ready = true;
  for (let i = 0; i < 4; i++) {
    makeSplatTexture(`ink_splat_${i}`, 1234 + i * 977);
  }
  const r = globalScene.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
  if (r?.pipelines) {
    r.pipelines.addPostPipeline("InkGradePostFX", InkGradePostFX);
    const cam = globalScene.cameras.main;
    cam.setPostPipeline(InkGradePostFX);
    try {
      cam.postFX?.addBloom(0xffffff, 1, 1, 0.8, 0.35, 4);
    } catch {
      /* bloom optional */
    }
  }
}

/** Ink burst on the hit target, coloured by the move's type. */
export function inkHit(target: Pokemon, moveType = 0, strong = false): void {
  try {
    initAgentFx();
    const sprite = target.getSprite();
    if (!sprite) {
      return;
    }
    const m = sprite.getWorldTransformMatrix();
    const x = m.tx;
    const y = m.ty - sprite.displayHeight * 0.45;
    const tint = TYPE_INK[moveType] ?? 0xffffff;
    const k = (globalScene as any).field?.scale || 6;
    const n = strong ? 14 : 8;
    for (let i = 0; i < n; i++) {
      const key = `ink_splat_${i % 4}`;
      const p = globalScene.add.image(x, y, key).setTint(tint).setDepth(1000).setScale(0.1 * k);
      p.setRotation(Math.random() * Math.PI * 2);
      const a = Math.random() * Math.PI * 2;
      const d = ((strong ? 22 : 15) + Math.random() * 12) * (k / 6) * 6;
      globalScene.tweens.add({
        targets: p,
        x: x + Math.cos(a) * d,
        y: y + Math.sin(a) * d * 0.7 + k,
        scale: (0.18 + Math.random() * (strong ? 0.3 : 0.18)) * k,
        duration: 220,
        ease: "Cubic.easeOut",
        onComplete: () =>
          globalScene.tweens.add({
            targets: p,
            alpha: 0,
            y: p.y + 3 * k, // drip
            scaleY: p.scaleY * 1.3,
            duration: 520,
            delay: 160,
            ease: "Quad.easeIn",
            onComplete: () => p.destroy(),
          }),
      });
    }
    // squash & stretch punch on the target
    const sx = sprite.scaleX;
    const sy = sprite.scaleY;
    globalScene.tweens.add({
      targets: sprite,
      scaleX: sx * 1.12,
      scaleY: sy * 0.88,
      duration: 70,
      yoyo: true,
      ease: "Quad.easeOut",
      onComplete: () => sprite.setScale(sx, sy),
    });
    globalScene.cameras.main.shake(strong ? 160 : 90, strong ? 0.006 : 0.003);
  } catch (e) {
    console.warn("inkHit", e);
  }
}
